package com.ems.dto;

import com.ems.entity.EmploymentStatus;
import io.swagger.v3.oas.annotations.media.Schema;
import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;

import java.math.BigDecimal;
import java.time.LocalDate;

/** Payload for creating or updating an employee. The Employee ID is generated by the database. */
public record EmployeeRequest(

        @Schema(example = "Priya Sharma")
        @NotBlank(message = "Full name is required")
        @Size(max = 100, message = "Full name must be at most 100 characters")
        String fullName,

        @Schema(example = "priya.sharma@example.com")
        @NotBlank(message = "Email is required")
        @Size(max = 150, message = "Email must be at most 150 characters")
        @Pattern(regexp = "^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$", message = "Email must be a valid address")
        String email,

        @Schema(example = "+91 98765 43210")
        @NotBlank(message = "Phone number is required")
        @Pattern(regexp = "^\\+?[0-9][0-9\\s-]{5,18}[0-9]$",
                message = "Phone number must be 7-20 digits and may contain spaces, hyphens and a leading +")
        String phoneNumber,

        @Schema(example = "Engineering")
        @NotBlank(message = "Department is required")
        @Size(max = 100, message = "Department must be at most 100 characters")
        String department,

        @Schema(example = "Backend Developer")
        @NotBlank(message = "Designation is required")
        @Size(max = 100, message = "Designation must be at most 100 characters")
        String designation,

        @Schema(example = "2024-07-01", type = "string", format = "date")
        @NotNull(message = "Date of joining is required")
        LocalDate dateOfJoining,

        @Schema(example = "850000.00")
        @NotNull(message = "Salary is required")
        @DecimalMin(value = "0.0", inclusive = false, message = "Salary must be greater than 0")
        @Digits(integer = 10, fraction = 2, message = "Salary can have at most 10 digits and 2 decimal places")
        BigDecimal salary,

        @Schema(example = "ACTIVE")
        @NotNull(message = "Employment status is required (ACTIVE or INACTIVE)")
        EmploymentStatus status
) {
}
